package Operaters;

public class Assignment10 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=5;
		int b=3;
		
		int result=++a - --b + a-- - b++;
		System.out.println(result);
		System.out.println("value of a:"+a);
		System.out.println("value of b:"+b);

	}

}
